void EditorFrame::CompleteRefinement(WorkResult& r){if(r.command==ExportSelectedSvg){ImageSaved(r.path);return;}if(r.revision!=revision_||r.expected!=Selection()){status_.SetWindowText(Tr(Text::Busy));return;}if(r.command==RepeatLastEffect&&(r.maskEpoch!=maskEpoch_||r.preview!=cropGeneration_||r.colorCrop!=cropRegion_||CRect(r.screen)!=pixelSelection_||r.colorTool!=style_.tool))return;if(r.command==SweepObjects){if(sweepMode_&&style_.tool==core::Tool::Select&&r.preview==sweepEpoch_)SetSelection(std::move(r.selected));return;}if(!r.colorChanged){status_.SetWindowText(Tr(Text::RefinementUnchanged));return;}if(!r.state.base||r.image.Empty()||r.thumbnail.Empty())throw std::runtime_error("Incomplete prepared editor result");document_.Commit(std::move(r.state));image_=std::move(r.image);thumbnail_=std::move(r.thumbnail);dirty_=true;++revision_;++previewGeneration_;rendered_=revision_;renderPending_=false;CancelMask();CancelCrop();pixelSelection_.SetRectEmpty();selected_=-1;SetSelection(std::move(r.selected));ClampViewport();NotifyWorkspace();if(r.recipe)RememberRecipe(*r.recipe);status_.SetWindowText(Tr(Text::RefinementApplied));InvalidateRect(canvas_,FALSE);}
